import {focusView,focusSummary,bindFocusView,toolRole} from './learning-plan.mjs';
import {STATUSES,escapeHtml as h,filterTools,cleanProgress,uniqueSources} from './utils.js';
const main=document.querySelector('main'),KEY='christrovato-software-atlas-v1';
let tools=[],editorial={},byId=new Map(),saved={},compare=[],filters={},toastTimer;
const priorityLabel={core:'Foundations & support',branch:'Specialty depth',explore:'Explore'};
const coreOrder=['python','freecad','solidworks','cpp','matlab','c','linux','numpy','matplotlib','jupyter','vscode','git','github','opencv','ros-2'];
const sortTools=a=>[...a].sort((a,b)=>{const ra=coreOrder.indexOf(a.id),rb=coreOrder.indexOf(b.id);if(ra>=0||rb>=0)return(ra<0?999:ra)-(rb<0?999:rb);return a.start.localeCompare(b.start)||a.name.localeCompare(b.name);});
const getTools=ids=>ids.map(id=>byId.get(id)).filter(Boolean);
const chips=ids=>getTools(ids).map(t=>`<a class="chip" href="#tool/${t.id}">${h(t.name)}</a>`).join('');
const sourceLink=s=>`<a class="source-link" href="${h(s.url)}" target="_blank" rel="noopener noreferrer">${h(s.title)} ↗<small>${h(new URL(s.url).hostname)}</small></a>`;
const title=(eyebrow,heading,body)=>`<div class="page-heading"><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1><p class="lede">${body}</p></div>`;
function toast(text){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),2600);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:1,saved,compare}));}catch{toast('Browser storage is unavailable. Export your list to keep it.');}updateChrome();}
function updateChrome(){document.querySelectorAll('[data-action="save"][data-id]').forEach(b=>{if(b.closest('.saved-row'))return;const yes=!!saved[b.dataset.id],detail=!!b.closest('.learning-card');b.setAttribute('aria-pressed',String(yes));b.textContent=detail?(yes?'✓ In your learning list':'+ Add to my learning list'):(yes?'✓ Saved':'+ Save');if(!detail)b.setAttribute('aria-label',`${yes?'Remove':'Save'} ${byId.get(b.dataset.id)?.name||''}`);});const progress=document.querySelector('#progress');if(progress&&saved[progress.dataset.progress]){progress.value=saved[progress.dataset.progress].status;const blank=progress.querySelector('option[value=""]');if(blank)blank.disabled=true;}document.querySelector('#saved-count').textContent=Object.keys(saved).length;const tray=document.querySelector('#comparison-tray');tray.hidden=!compare.length;tray.innerHTML=compare.length?`<span>${compare.length} of 3 selected</span><a href="#compare">Compare tools →</a><button data-action="clear-compare" aria-label="Clear comparison">Clear ×</button>`:'';}
function card(t){const isSaved=!!saved[t.id],isCompared=compare.includes(t.id);return `<article class="tool-card" data-tool="${t.id}"><div class="card-top"><span class="tool-icon" aria-hidden="true">${h(t.name.replace(/^(Ansys |NASA |NVIDIA |Siemens |Autodesk )/,'').slice(0,2))}</span><span class="badge ${t.priority} lp-role">${h(toolRole(t).label)}</span></div><h3><a href="#tool/${t.id}">${h(t.name)}</a></h3><p>${h(t.summary)}</p><p class="lp-tool-note">${h(toolRole(t).when)}</p><div class="tool-meta"><span>Planning window: ${h(t.start)}</span><span>${h(t.kind)} · ${h(t.depth)}</span></div><div class="card-actions"><button data-action="save" data-id="${t.id}" aria-label="${isSaved?'Remove':'Save'} ${h(t.name)}" aria-pressed="${isSaved}">${isSaved?'✓ Saved':'+ Save'}</button><button data-action="compare" data-id="${t.id}" aria-label="Compare ${h(t.name)}" aria-pressed="${isCompared}">${isCompared?'✓ Compare':'Compare'}</button><a href="#tool/${t.id}" aria-label="Explore ${h(t.name)}">Explore ↗</a></div></article>`;}
function cards(list){return `<div class="tool-grid">${list.map(card).join('')}</div>`;}
function pathCard(p){const n=tools.filter(t=>t.specialties.includes(p.id)).length;return `<a class="path-card" href="#path/${p.id}" style="--accent:${h(p.color||'#d7f78b')}"><span class="symbol" aria-hidden="true">${h(p.symbol||'⌁')}</span><h3>${h(p.name)}</h3><p>${h(p.short)}</p><div class="path-footer"><span>${n} tools to consider</span><span>Explore pathway ↗</span></div></a>`;}
function diagram(){return `<svg class="diagram" viewBox="0 0 500 450" role="img" aria-label="An engineering workflow connects design, code, simulation and testing around a spacecraft concept."><defs><radialGradient id="glow"><stop stop-color="#30606d" stop-opacity=".5"/><stop offset="1" stop-color="#0b1019" stop-opacity="0"/></radialGradient><linearGradient id="metal" x2="1" y2="1"><stop stop-color="#bfd3d5"/><stop offset=".48" stop-color="#527382"/><stop offset="1" stop-color="#213743"/></linearGradient><pattern id="solar" width="15" height="18" patternUnits="userSpaceOnUse"><rect width="13" height="16" fill="#183b50" stroke="#80b1bc" stroke-width=".3"/></pattern></defs><circle cx="260" cy="225" r="215" fill="url(#glow)"/><g fill="none" stroke="#7899a1" stroke-opacity=".25"><ellipse cx="260" cy="230" rx="205" ry="134" transform="rotate(-32 260 230)"/><ellipse cx="260" cy="230" rx="165" ry="194" transform="rotate(-32 260 230)" stroke-dasharray="2 7"/><circle cx="260" cy="230" r="97"/><path d="M20 230H490M260 25V425" stroke-dasharray="2 7"/></g><g transform="translate(260 228) rotate(-25)"><rect x="-156" y="-60" width="81" height="126" fill="url(#solar)" stroke="#779da6"/><rect x="78" y="-60" width="81" height="126" fill="url(#solar)" stroke="#779da6"/><path d="M-77 2H-55M53 2H78" stroke="#96b1b8" stroke-width="6"/><rect x="-50" y="-45" width="102" height="86" rx="12" fill="url(#metal)" stroke="#b8ced0"/><ellipse cx="51" cy="-2" rx="12" ry="43" fill="#294450" stroke="#b8ced0"/><path d="M-15-43V-73L26-98L63-76L86-99" fill="none" stroke="#9eb7b4" stroke-width="7"/><g fill="#20373e" stroke="#d7f78b" stroke-width="2"><circle cx="-15" cy="-73" r="7"/><circle cx="26" cy="-98" r="7"/><circle cx="63" cy="-76" r="6"/></g><path d="M84-102l12-6 8 15-12 6z" fill="#64858e" stroke="#b8ced0"/><rect x="-20" y="42" width="35" height="19" fill="#78969c" stroke="#b8ced0"/></g><g font-size="10" letter-spacing="1.7"><g fill="#d7f78b"><circle cx="103" cy="89" r="4"/><text x="118" y="93">01 / DESIGN</text><circle cx="358" cy="112" r="4"/><text x="373" y="116">02 / CODE</text></g><g fill="#91cce5"><circle cx="47" cy="322" r="4"/><text x="62" y="326">03 / SIMULATE</text><circle cx="326" cy="362" r="4"/><text x="341" y="366">04 / TEST</text></g></g><text x="260" y="433" fill="#8096a4" text-anchor="middle" font-size="8" letter-spacing="2">ONE SYSTEM. MANY CONNECTED SKILLS.</text></svg>`;}
function home(){const sourceCount=uniqueSources(tools,editorial.evidence).length;return `<section class="hero"><div><p class="eyebrow"><span class="status-dot"></span> YOUR ENGINEERING TOOLKIT · 2026—2035</p><h1>Learn the tools.<br>Build what<br>comes <em>next.</em></h1><p class="lede">From your first CAD model to autonomous robots and spacecraft. Understand the software, find your direction, and turn curiosity into capability.</p><div class="hero-actions"><a class="button primary" href="#catalog">Explore the software ↗</a><a class="button" href="#roadmap">Your path to 2035 →</a></div><p class="hero-note">A companion to your Frontier Atlas · Built for exploration and depth.</p></div>${diagram()}</section>${focusSummary('atlas')}<div class="statbar"><div class="stat"><strong>${tools.length}</strong><span>TOOLS, LANGUAGES & FRAMEWORKS</span></div><div class="stat"><strong>${editorial.specialties.length}</strong><span>ENGINEERING PATHWAYS</span></div><div class="stat"><strong>${sourceCount}</strong><span>LINKED PRIMARY SOURCES</span></div><div class="stat"><strong>2035</strong><span>YOUR LEARNING HORIZON</span></div></div><section><div class="section-title"><div><p class="eyebrow">START WITH A CONNECTED CORE</p><h2>Your first steps already fit together.</h2><p>CAD and Python deserve sustained practice. Linux and Git grow alongside them. Add each next tool through a project you can explain.</p></div></div><div class="start-grid"><article class="start-card"><span>01</span><div><h3>Design a physical thing</h3><p>Choose one CAD package. Model a cartridge, bracket or mechanism; measure it, revise it and make a drawing.</p><div class="chips">${chips(['freecad','solidworks','autodesk-fusion'])}</div></div></article><article class="start-card"><span>02</span><div><h3>Give yourself computing tools</h3><p>Write small Python programs, plot measurements and learn the terminal. Keep a version history as you go.</p><div class="chips">${chips(['python','linux','git','matplotlib'])}</div></div></article><article class="start-card"><span>03</span><div><h3>Make hardware respond</h3><p>After comfortable Python basics, add C++. Learn C through an embedded project and MATLAB when coursework calls for it; these need not start together.</p><div class="chips">${chips(['cpp','c','matlab','opencv'])}</div></div></article><article class="start-card"><span>04</span><div><h3>Connect, simulate, validate</h3><p>Bring together control, robotics and physical analysis as your mathematics and experiments deepen.</p><div class="chips">${chips(['ros-2','simulink','ansys-mechanical','basilisk'])}</div></div></article></div></section><section><div class="section-title"><div><p class="eyebrow">CHOOSE THE WORK THAT INTERESTS YOU</p><h2>Different missions. Different toolkits.</h2></div><a class="text-link" href="#paths">All ${editorial.specialties.length} pathways ↗</a></div><div class="path-grid">${['robotics','habitats','mechanisms','gnc','propulsion','defense'].map(id=>editorial.specialties.find(p=>p.id===id)).filter(Boolean).map(pathCard).join('')}</div></section><div class="banner"><div><h3>A little familiarity can be a useful outcome.</h3><p>Explore a tool, try a small task, then choose whether it deserves more time. Save your interests and record what you actually did.</p></div><a class="button" href="#saved">Build your learning list →</a></div><div class="section-title"><div><p class="eyebrow">THREE DEPTHS OF LEARNING</p><h2>Know what “learning it” means.</h2></div></div>${depthStrip()}`;}
function depthStrip(){return `<div class="depth-strip"><div class="depth-box"><h3>Explore</h3><p>Explain what it does, run a guided example, and know when a specialist would use it.</p></div><div class="depth-box"><h3>Working</h3><p>Complete a small project, adapt an example, troubleshoot common errors and check the output.</p></div><div class="depth-box"><h3>Proficient → specialist</h3><p>Own a repeatable workflow and defend its assumptions. Expert depth grows through difficult projects, validation and review.</p></div></div>`;}
function catalog(){return `${title('THE FULL FIELD GUIDE','Find your next <em>tool.</em>','Search by name, task or topic. Filter the map to your current stage, or explore what a different specialty uses.')}<p class="inline-note">Python + one CAD now; C++ after comfortable Python basics. Supporting tools need working proficiency. <a href="#focus">Read the full order and readiness checkpoints →</a></p><div class="toolbar"><div class="search-row"><label class="search-wrap"><span aria-hidden="true">⌕</span><span class="visually-hidden">Search software</span><input type="search" id="search" placeholder="Try: Python, thermal, CAD, robotics…" value="${h(filters.q||'')}" autocomplete="off"></label><button class="button" data-action="reset">Reset</button></div><div class="filter-row"><select id="filter-family" aria-label="Software family"><option value="">All software families</option>${[...new Set(tools.map(t=>t.family))].sort().map(x=>`<option ${filters.family===x?'selected':''}>${h(x)}</option>`).join('')}</select><select id="filter-specialty" aria-label="Engineering specialty"><option value="">All engineering pathways</option>${editorial.specialties.map(p=>`<option value="${p.id}" ${filters.specialty===p.id?'selected':''}>${h(p.name)}</option>`).join('')}</select><select id="filter-priority" aria-label="Learning priority"><option value="">All learning priorities</option>${Object.entries(priorityLabel).map(([v,l])=>`<option value="${v}" ${filters.priority===v?'selected':''}>${l}</option>`).join('')}</select><select id="filter-phase" aria-label="Suggested start"><option value="">Any suggested start</option>${editorial.phases.map(p=>`<option ${filters.phase===p.id?'selected':''}>${h(p.id)}</option>`).join('')}</select></div></div><div class="results-line"><span id="result-count" role="status" aria-live="polite"></span><span>Readiness first · dates are flexible</span></div><div id="catalog-results"></div>`;}
function updateCatalog(){const found=sortTools(filterTools(tools,filters));document.querySelector('#result-count').textContent=`${found.length} of ${tools.length} tools`;document.querySelector('#catalog-results').innerHTML=found.length?cards(found):`<div class="empty"><h2>No tools match those filters.</h2><p>Try a broader topic or clear the filters.</p><button class="button" data-action="reset">Show all software</button></div>`;const q=new URLSearchParams(Object.entries(filters).filter(([,v])=>v));history.replaceState(null,'',`#catalog${q.size?'?'+q:''}`);}
function paths(){return `${title('EXPLORE THE ENGINEERING WORK','One degree.<br><em>Many directions.</em>','Choose a pathway to see its purpose, foundations and connected software. Aircraft, spacecraft, robotics and defense share many tools; the engineering questions make the difference.')}<div class="path-grid">${editorial.specialties.map(pathCard).join('')}</div><div class="banner"><div><h3>Explore the careers behind these toolkits.</h3><p>Your Frontier Atlas covers 26 career specialties and deeper niches. This companion groups the software into practical workflows.</p></div><a class="button" href="https://www.christrovato.com/aero_specialization_decision">Open Frontier Atlas ↗</a></div>`;}
function pathPage(id){const p=editorial.specialties.find(p=>p.id===id);if(!p)return missing();const selected=getTools(p.recommended),others=sortTools(tools.filter(t=>t.specialties.includes(id)&&!p.recommended.includes(t.id)));return `<div class="breadcrumb"><a href="#paths">All pathways</a> / ${h(p.name)}</div>${title('ENGINEERING PATHWAY',h(p.name),h(p.description))}<div class="phase-intro"><div><p class="eyebrow">THE FOUNDATIONS</p><p>${h(p.foundation)}</p><p class="eyebrow" style="margin-top:25px">HOW THE WORK CONNECTS</p><div class="chips">${p.workflow.map((s,i)=>`<span class="chip">${i+1}. ${h(s)}</span>`).join('')}</div></div><div class="outcome"><h3>A first experiment</h3><p>${h(p.project)}</p></div></div><div class="section-title"><div><h2>A useful starting toolkit</h2><p>Pick the relevant tools for one project; alternatives may fill the same role.</p></div></div>${cards(selected)}<div class="banner"><div><h3>What deeper expertise looks like</h3><p>${h(p.depth)}</p></div><a class="button" href="#catalog?specialty=${p.id}">Filter this pathway →</a></div>${others.length?`<div class="section-title"><div><h2>Further tools to recognize</h2><p>Explore these as a class, team, employer or research question creates a reason.</p></div></div>${cards(others)}`:''}`;}
function detail(id){const t=byId.get(id);if(!t)return missing();const s=saved[id];return `<div class="breadcrumb"><a href="#catalog">All software</a> / ${h(t.family)}</div>${title(`${h(t.kind)} · ${h(t.family)}`,h(t.name),h(t.summary))}<div class="detail-layout"><div class="detail-body"><section><h2>When to learn this</h2><p>${h(toolRole(t).when)}</p><a class="text-link" href="#focus">Check the learning order and readiness →</a></section><section><h2>Where it fits</h2><p>${h(t.why)}</p><div class="chips">${t.specialties.map(id=>editorial.specialties.find(p=>p.id===id)).filter(Boolean).map(p=>`<a href="#path/${p.id}" class="chip">${h(p.name)} ↗</a>`).join('')}</div></section><section><div class="experiment"><p class="eyebrow">YOUR FIRST HANDS-ON EXPERIENCE</p><p>${h(t.firstProject)}</p></div></section><section><h2>Learn these foundations first</h2><ul>${t.prerequisites.map(x=>`<li>${h(x)}</li>`).join('')}</ul><p class="subtle">A first guided example can come earlier. Independent engineering use requires the relevant fundamentals and checks.</p></section><section><h2>Access & setup</h2><p><strong>Access:</strong> ${h(t.access)}</p><p><strong>Platform:</strong> ${h(t.platform)}</p><p class="subtle">Access checked November 2026. Confirm current eligibility, licenses and system requirements before installing or paying.</p></section>${t.alternatives.length?`<section><h2>Related alternatives</h2><p>${t.alternatives.map(name=>{const match=tools.find(x=>x.name.toLowerCase()===name.toLowerCase());return match?`<a class="text-link" href="#tool/${match.id}">${h(name)} ↗</a>`:h(name);}).join(' · ')}</p><p class="subtle">Related tools overlap in purpose; they are not necessarily interchangeable.</p></section>`:''}<section><h2>Official sources & next steps</h2>${t.sources.map(sourceLink).join('')}</section></div><aside class="learning-card"><dl><dt>Recommended role</dt><dd><span class="badge ${t.priority} lp-role">${h(toolRole(t).label)}</span></dd><dt>Flexible planning window</dt><dd>${h(t.start)}</dd><dt>Suggested depth by 2035</dt><dd>${h(t.depth)}</dd></dl><p class="subtle">A planning recommendation for this guide, not a course or employer requirement.</p><button class="button ${s?'':'primary'}" data-action="save" data-id="${id}" aria-pressed="${!!s}">${s?'✓ In your learning list':'+ Add to my learning list'}</button><button class="button" data-action="compare" data-id="${id}" aria-pressed="${compare.includes(id)}">${compare.includes(id)?'✓ Selected for comparison':'Compare with another tool'}</button><label for="progress">Your experience</label><select id="progress" data-progress="${id}"><option value="" ${s?'disabled':''}>Not recorded</option>${STATUSES.map(v=>`<option ${s?.status===v?'selected':''}>${v}</option>`).join('')}</select><label for="learning-note">What did you try or learn?</label><textarea id="learning-note" data-note="${id}" maxlength="5000" placeholder="An experiment, a question, or a link to your work…">${h(s?.note||'')}</textarea><p class="subtle">Saved in this browser. Export from My learning list for a backup.</p></aside></div>`;}
function roadmap(phase){const p=editorial.phases.find(x=>x.id===phase)||editorial.phases[0];return `${title('A PROGRESSION, NOT A RACE','From first exposure<br>to <em>real depth.</em>','Build the foundations, connect them through projects, then specialize. Your proposed 2029 transfer and 2032 graduation shape the early stages; 2033–2035 develops professional depth.')}${focusSummary('atlas')}<div class="phase-tabs" role="tablist" aria-label="Learning period">${editorial.phases.map(x=>`<button class="phase-tab" role="tab" aria-selected="${x.id===p.id}" data-action="phase" data-phase="${h(x.id)}"><strong>${h(x.id)}</strong><span>${h(x.label)}</span></button>`).join('')}</div><section role="tabpanel" aria-label="${h(p.id)} learning plan"><div class="phase-intro"><div><p class="eyebrow">${h(p.label)}</p><h2>${h(p.title)}</h2><p>${h(p.description)}</p></div><div class="outcome"><h3>A meaningful outcome</h3><p>${h(p.outcome)}</p></div></div><div class="steps">${p.steps.map((s,i)=>`<article class="step"><span class="num">0${i+1}</span><h3>${h(s.title)}</h3><p>${h(s.body)}</p></article>`).join('')}</div><div class="section-title"><div><h2>Tools to connect in this stage</h2><p>Continue using the earlier foundations. Suggested tools are a menu for the work you choose.</p></div></div>${cards(getTools(p.focus))}</section><div class="banner"><div><h3>By 2035: breadth you can explain, depth you can demonstrate.</h3><p>Develop specialist ability in one workflow, working familiarity in adjacent ones, and informed awareness of the rest. Revisit this plan when your courses, interests or team change.</p></div></div>${depthStrip()}<p class="inline-note">Dates are planning scenarios. MATLAB preparation aligns with proposed ENGR 221 in fall 2028; controls and embedded work build toward the proposed 2030 UCSD sequence. Actual admission, prerequisites, course availability and software choices must be confirmed.</p>`;}
function savedPage(){const list=sortTools(getTools(Object.keys(saved)));return `${title('YOUR PERSONAL LEARNING LIST','Turn interest into<br><em>experience.</em>','Save a tool, try something small, and record the evidence. Your statuses are personal notes—not a certification or an automatic assessment.')}<div class="saved-summary">${STATUSES.map(s=>`<div><strong>${list.filter(t=>saved[t.id].status===s).length}</strong><span>${s}</span></div>`).join('')}</div><div class="actions"><button class="button primary" data-action="export">Export my list ↓</button><button class="button" data-action="import">Import a backup ↑</button><input type="file" id="import-file" accept=".json,application/json" hidden><a class="text-link" href="#catalog">Find more tools ↗</a></div><p class="inline-note">Your list stays in this browser on this website. Export it before switching devices or clearing browser data. Import merges recognized tools with your current list.</p>${list.length?list.map(t=>`<article class="saved-row"><div><h3><a href="#tool/${t.id}">${h(t.name)} ↗</a></h3><p>${h(t.summary)}</p>${saved[t.id].note?`<p>Note: ${h(saved[t.id].note.slice(0,180))}${saved[t.id].note.length>180?'…':''}</p>`:''}</div><select aria-label="Experience with ${h(t.name)}" data-progress="${t.id}">${STATUSES.map(s=>`<option ${saved[t.id].status===s?'selected':''}>${s}</option>`).join('')}</select><button data-action="save" data-id="${t.id}" aria-label="Remove ${h(t.name)} from learning list">Remove ×</button></article>`).join(''):`<div class="empty"><h2>Your list starts with curiosity.</h2><p>Open the catalog and save the first tool you want to understand.</p><a class="button" href="#catalog">Explore software →</a></div>`}`;}
function comparison(){const list=getTools(compare);if(!list.length)return `${title('SIDE BY SIDE','Compare the <em>roles.</em>','Select up to three tools in the catalog, then compare their purposes, prerequisites and learning depth.')}<a class="button primary" href="#catalog">Choose tools →</a>`;const rows=[['What it does',t=>h(t.summary)],['Where it fits',t=>h(t.why)],['First experience',t=>h(t.firstProject)],['Foundations',t=>t.prerequisites.map(h).join('<br>')],['Suggested start',t=>h(t.start)],['Suggested depth',t=>h(t.depth)],['Access',t=>h(t.access)],['Platform',t=>h(t.platform)]];return `${title('SIDE BY SIDE','Compare the <em>roles.</em>','Some tools are alternatives. Others work together. Compare the engineering job they do before choosing where to spend time.')}<div class="table-wrap"><table class="compare-table"><thead><tr><th>Tool / question</th>${list.map(t=>`<th><a href="#tool/${t.id}">${h(t.name)} ↗</a></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th scope="row">${label}</th>${list.map(t=>`<td>${fn(t)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="actions"><a class="button" href="#catalog">Choose another tool</a><button class="button" data-action="clear-compare">Clear comparison</button></div>`;}
function sourcesPage(){const sources=uniqueSources(tools,editorial.evidence);return `${title('EVIDENCE & PLAIN ENGLISH','Understand the map.<br><em>Check the sources.</em>','The catalog is a broad, curated guide to major aerospace software workflows—not every product on the market. Capabilities and access are grounded in primary sources; priorities and dates are editorial recommendations.')}<div class="text-columns"><div><h3>What the recommendations mean</h3><p>Build your core identifies reusable foundations for this learning journey. Specialty depth marks tools to learn through a chosen engineering workflow. Explore means a guided example and a clear understanding of the tool’s role can be enough.</p><p>The 2035 horizon is a learning plan, not a forecast of which brands will dominate. Recheck software versions, licenses and employers’ actual needs when making a decision.</p></div><div><h3>How this connects to your other atlas</h3><p>This guide carries forward the Frontier Atlas’s interests in mechanisms, robotics, spacecraft, habitats and flight, while broadening into the adjacent disciplines. It does not lock you into one specialization.</p><a class="text-link" href="https://www.christrovato.com/aero_specialization_decision">Visit the career specialization atlas ↗</a><p>Research snapshot: 2 November 2026. Revisit the official sources as tools and learning opportunities change.</p></div></div><div class="section-title"><div><h2>Evidence from courses and real work</h2><p>Examples show how tools fit into particular workflows. A job listing is not a universal degree requirement or a promise of future hiring.</p></div></div>${editorial.evidence.map(e=>`<details><summary>${h(e.title)}</summary><p>${h(e.note)}</p>${sourceLink(e)}</details>`).join('')}<div class="section-title"><div><h2>The acronyms, explained</h2></div></div><div class="glossary">${editorial.glossary.map(g=>`<div><h3>${h(g.term)}</h3><p>${h(g.definition)}</p></div>`).join('')}</div><div class="section-title"><div><h2>${sources.length} linked primary references</h2><p>Each tool profile links directly to the relevant vendor, open-source project, agency or university.</p></div></div><div class="source-list">${sources.map(sourceLink).join('')}</div>`;}
function missing(){return `${title('PAGE NOT FOUND','Choose another <em>direction.</em>','That tool or pathway is not in this edition of the atlas.')}<a href="#catalog" class="button">Open the software catalog →</a>`;}
function route(focus=false){const raw=location.hash.slice(1)||'home';const [path,query='']=raw.split('?');const [view,id]=path.split('/');const params=new URLSearchParams(query);if(view==='catalog')filters=Object.fromEntries(['q','family','priority','phase','specialty'].map(k=>[k,params.get(k)||'']));const pages={home,focus:()=>focusView('atlas'),paths,catalog,saved:savedPage,compare:comparison,sources:sourcesPage};main.innerHTML=view==='tool'?detail(id):view==='path'?pathPage(id):view==='roadmap'?roadmap(params.get('phase')):(pages[view]||missing)();bindFocusView(main);if(view==='catalog')updateCatalog();const active=view==='tool'?'catalog':view==='path'?'paths':view;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===active);if(a.dataset.nav===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=`${view==='tool'?(byId.get(id)?.name||'Software'):view==='path'?(editorial.specialties.find(p=>p.id===id)?.name||'Pathway'):({home:'Aerospace Engineering, 2026–2035',focus:'Focus & Readiness',catalog:'Explore Software',paths:'Engineering Pathways',roadmap:'Roadmap to 2035',saved:'My Learning List',sources:'Sources & Glossary',compare:'Compare Tools'}[view]||'Explore')} · The Software Atlas`;updateChrome();if(focus){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();main.focus();main.scrollIntoView();return;}const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;if(action==='save'&&byId.has(id)){const removing=!!saved[id];if(removing)delete saved[id];else saved[id]={status:'Curious',note:''};persist();if(location.hash.startsWith('#catalog'))updateCatalog();else{const y=scrollY;route();scrollTo(0,y);}toast(removing?'Removed from your learning list.':'Saved to your learning list.');}else if(action==='compare'&&byId.has(id)){if(compare.includes(id))compare=compare.filter(x=>x!==id);else if(compare.length<3)compare.push(id);else{return toast('Choose up to three tools. Remove one to add another.');}persist();const y=scrollY;route();scrollTo(0,y);}else if(action==='clear-compare'){compare=[];persist();const y=scrollY;route();scrollTo(0,y);}else if(action==='reset'){filters={};main.innerHTML=catalog();updateCatalog();document.querySelector('#search').focus();}else if(action==='phase'){location.hash=`roadmap?phase=${encodeURIComponent(b.dataset.phase)}`;}else if(action==='export'){const blob=new Blob([JSON.stringify({format:'software-atlas',version:1,exportedAt:new Date().toISOString(),saved},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='my-software-learning-list.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Learning-list backup exported.');}else if(action==='import'){document.querySelector('#import-file').click();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){filters.q=e.target.value;updateCatalog();}if(e.target.dataset.note){const id=e.target.dataset.note;saved[id]??={status:'Curious',note:''};saved[id].note=e.target.value.slice(0,5000);persist();}});
document.addEventListener('change',async e=>{if(e.target.id.startsWith('filter-')){filters[e.target.id.slice(7)]=e.target.value;updateCatalog();}if(e.target.dataset.progress){const id=e.target.dataset.progress;if(!STATUSES.includes(e.target.value))return;saved[id]??={status:'Curious',note:''};saved[id].status=e.target.value;persist();if(location.hash.startsWith('#saved'))route();else if(location.hash.startsWith('#tool/')){const y=scrollY;route();scrollTo(0,y);}toast('Experience updated.');}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Please choose an atlas backup smaller than 2 MB.');const incoming=cleanProgress(JSON.parse(await file.text()),new Set(byId.keys()));saved={...saved,...incoming};persist();route();toast(`Imported ${Object.keys(incoming).length} recognized tools.`);}catch(err){toast(err.message||'Unable to import this file.');}}});
window.addEventListener('hashchange',()=>route(true));
async function init(){try{const responses=await Promise.all(['data.json','editorial.json'].map(f=>fetch(f)));if(responses.some(r=>!r.ok))throw Error('The guide could not be loaded.');[tools,editorial]=await Promise.all(responses.map(r=>r.json()));byId=new Map(tools.map(t=>[t.id,t]));try{const data=JSON.parse(localStorage.getItem(KEY)||'null');if(data){saved=cleanProgress(data,new Set(byId.keys()));compare=Array.isArray(data.compare)?[...new Set(data.compare)].filter(id=>byId.has(id)).slice(0,3):[];}}catch{}route();}catch(error){main.innerHTML=`<div class="empty"><h1>The atlas could not load.</h1><p>Please refresh to try again.</p><p>${h(error.message)}</p></div>`;}}
init();
